function broadcastState(campaignId,key,value,meta={}){for(const sub of campaignSubscribers(campaignId)){if(meta.sourceClientId&&sub.clientId&&sub.clientId===meta.sourceClientId)continue;if(!canSubscriberReceive(sub,key,meta))continue;writeSse(sub.res,'state',{type:'state',key,value:sub.session.role==='player'?visibleValueForPlayer(key,value):value,heroId:meta.heroId||null,campaignId,updatedAt:new Date().toISOString(),sourceClientId:meta.sourceClientId||null});}}
