function openEvents(req,res,url,session){const headers={...corsHeaders(),'Content-Type':'text/event-stream; charset=utf-8','Cache-Control':'no-cache, no-transform','Connection':'keep-alive','X-Accel-Buffering':'no'};res.writeHead(200,headers);res.write(': connected\n\n');const clientId=clientIdFromRequest(req,url);for(const old of campaignSubscribers(session.campaignId)){if(clientId&&old.clientId===clientId&&old.session.sid===session.sid){try{old.res.end();}catch{}removeSubscriber(old.id);}}const id=crypto.randomUUID(),sub={id,res,session,clientId,connectedAt:Date.now()};subscribers.set(id,sub);if(!subscriberIdsByCampaign.has(session.campaignId))subscriberIdsByCampaign.set(session.campaignId,new Set());subscriberIdsByCampaign.get(session.campaignId).add(id);writeSse(res,'ready',{type:'ready',provider:repo.provider,campaignId:session.campaignId,campaignCode:session.campaignCode,role:session.role,heroId:session.heroId||null});broadcastPresence(session.campaignId);let closed=false;req.on('close',()=>{if(closed)return;closed=true;removeSubscriber(id);broadcastPresence(session.campaignId);});}
